// Always the connection's own user: the id comes from the session, never from the frame.
async function answerConversationList(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  frame: ListSessionsMessage
): Promise<void> {
  const summaries = (await sessionStore?.listFor?.(session.userId, {limit: frame.limit, before: frame.before})) ?? [];
